"""Regression test for https://github.com/eclipse-threadx/guix/issues/172.

GUIX Studio emits five static helper functions in the generated specification
file as soon as a project uses Screen Flow. Two of them,
gx_studio_action_parent_find() and gx_studio_animation_execute(), are reachable
only from the GX_ACTION_TYPE_ANIMATION handler and call the GUIX animation API,
which is compiled out when GX_ANIMATION_POOL_SIZE is 0. The generator must
therefore guard them with "#if (GX_ANIMATION_POOL_SIZE > 0)", otherwise a Screen
Flow project cannot be built with an empty animation pool.

The test runs in two stages:

1. Source check: every checked-in generated specification file that uses Screen
   Flow must guard the animation helpers. This stage needs no compiler.
2. Compile check: the same files are compiled with GX_ANIMATION_POOL_SIZE set to
   0. The MSVC warning about an implicit function declaration (C4013) is
   promoted to an error so that the missing gx_system_animation_get() macro is
   reported, which is what a linker or GCC 14 would reject.
"""

import argparse
import logging
import os
import shutil
import subprocess
import sys
import tempfile

import search_gxps

ANIMATION_HELPER = 'gx_studio_animation_execute'
ANIMATION_GUARD = '#if (GX_ANIMATION_POOL_SIZE > 0)'

# Every one of these must sit inside an ANIMATION_GUARD block. The first two are
# the definitions of the helpers that reference the animation API, the third is
# the switch case that calls them. A prototype or a call ends with a semicolon,
# so the check below ignores those lines and only looks at the definitions and
# at the case label.
GUARDED_LINES = ['static GX_WIDGET *gx_studio_action_parent_find(',
                 'static VOID gx_studio_animation_execute(',
                 'case GX_ACTION_TYPE_ANIMATION:']

# These projects were generated for GUIX 5.4.0 and 5.4.1, whose widget API is
# not source compatible with the current library, so they cannot be compiled
# standalone. The demo compile test skips them for the same reason. Their
# generated files are still covered by the source check below.
UNCOMPILABLE_PROJECTS = ['all_widgets_5_4_0', 'all_widgets_5_4_1']

# Scratch directories that some Studio projects generate into. They hold copies
# of the generated files, not sources, so they are not part of this test.
SCRATCH_DIRECTORIES = ['output_files', 'project_output_folder',
                       'xml_output_folder']

GX_USER_CONTENT = """/* Generated by test_animation_pool_size.py. Do not edit. */

#ifndef GX_USER_H
#define GX_USER_H

/* Build without the animation pool to make sure the code generated for Screen
   Flow does not reference the animation API. */
#define GX_ANIMATION_POOL_SIZE 0

#endif
"""

# count[total, passed, failed]
count_source = [0, 0, 0]
count_compile = [0, 0, 0]


def find_screen_flow_files(root_dir):
    """Return the generated specification files that use Screen Flow."""

    files = []
    for pathname in search_gxps.files_find(['*_specifications.c'], root_dir):
        if os.path.basename(os.path.dirname(pathname)) in SCRATCH_DIRECTORIES:
            continue

        with open(pathname, 'r') as source:
            if ANIMATION_HELPER in source.read():
                files.append(pathname)
    return sorted(files)


def check_source(pathname):
    """Verify that the animation helpers are guarded in one generated file."""

    with open(pathname, 'r') as source:
        lines = source.readlines()

    guard_depth = 0
    guarded = dict.fromkeys(GUARDED_LINES, False)

    for line in lines:
        stripped = line.strip()
        if stripped == ANIMATION_GUARD:
            guard_depth += 1
        elif stripped.startswith('#if'):
            if guard_depth:
                guard_depth += 1
        elif stripped.startswith('#endif'):
            if guard_depth:
                guard_depth -= 1
        elif guard_depth and not stripped.endswith(';'):
            for expected in guarded:
                if stripped.startswith(expected):
                    guarded[expected] = True

    missing = [expected for expected in GUARDED_LINES if not guarded[expected]]
    if missing:
        logging.error('**Error** %s: "%s" not guarded by "%s"',
                      pathname, '", "'.join(missing), ANIMATION_GUARD)
        return False
    return True


def compile_file(pathname, root_dir, gx_user_dir, output_dir):
    """Compile one generated file with an empty animation pool."""

    command = ['cl', '/nologo', '/c', '/W3',
               # An undeclared gx_system_animation_get() is only a warning for
               # MSVC. Promote it so that this test fails the way a GCC 14 or a
               # link step would.
               '/we4013',
               '/DGX_INCLUDE_USER_DEFINE_FILE',
               '/DWIN32', '/D_DEBUG', '/D_WINDOWS',
               '/D_CRT_SECURE_NO_WARNINGS',
               '/Fo' + os.path.join(output_dir, '')]

    for directory in [gx_user_dir,
                      os.path.dirname(pathname),
                      os.path.join(root_dir, 'common', 'inc'),
                      os.path.join(root_dir, 'ports', 'win32', 'inc'),
                      os.path.join(root_dir, 'ports', 'win32', 'lib', 'vs_2019')]:
        command += ['/I', directory]

    command.append(pathname)

    result = subprocess.run(command, stdout=subprocess.PIPE,
                            stderr=subprocess.STDOUT)
    output = result.stdout.decode(errors='replace')
    logging.debug(output)

    if result.returncode:
        logging.error('**Error** Compilation failed for %s', pathname)
        logging.error(output)
        return False
    return True


def write_test_result():
    logging.info('********************************************')
    logging.info(' Source checked files : %d', count_source[0])
    logging.info(' Passed : %d', count_source[1])
    logging.info(' Failed : %d', count_source[2])
    logging.info(' Compiled files : %d', count_compile[0])
    logging.info(' Passed : %d', count_compile[1])
    logging.info(' Failed : %d', count_compile[2])


def __main__():
    # Change the current working directory to the path of this file.
    current_path = os.path.split(os.path.realpath(__file__))[0]
    os.chdir(current_path)
    root_dir = os.path.realpath(os.path.join(current_path, '..', '..', '..'))

    parser = argparse.ArgumentParser(
        description='Test Screen Flow output with GX_ANIMATION_POOL_SIZE = 0.')
    parser.add_argument('--debug', action='store_true', dest='debug',
                        help='Print the debug logs to console.')
    args = parser.parse_args()

    logging.basicConfig(filename='animation_pool_size_test_log.txt',
                        filemode='w', level=logging.DEBUG, format='%(message)s')
    console = logging.StreamHandler()
    console.setLevel(logging.DEBUG if args.debug else logging.INFO)
    console.setFormatter(logging.Formatter('%(message)s'))
    logging.getLogger('').addHandler(console)

    files = []
    for directory in ['samples', os.path.join('test', 'example_internal'),
                      'tutorials']:
        files += find_screen_flow_files(os.path.join(root_dir, directory))

    if not files:
        logging.error('**Error** No Screen Flow specification file found.')
        return 1

    logging.info('Found %d Screen Flow specification files.', len(files))

    for pathname in files:
        count_source[0] += 1
        if check_source(pathname):
            count_source[1] += 1
        else:
            count_source[2] += 1

    if shutil.which('cl') is None:
        logging.warning('** Skipped ** cl.exe not found on PATH, the compile '
                        'stage of this test did not run. Run the test from a '
                        'Visual Studio developer command prompt.')
    else:
        work_dir = tempfile.mkdtemp(prefix='gx_animation_pool_size_')
        try:
            with open(os.path.join(work_dir, 'gx_user.h'), 'w') as gx_user:
                gx_user.write(GX_USER_CONTENT)

            for pathname in files:
                project = os.path.basename(os.path.dirname(pathname))
                if project in UNCOMPILABLE_PROJECTS:
                    logging.info('Skipping %s, it targets a legacy GUIX API.',
                                 pathname)
                    continue

                count_compile[0] += 1
                if compile_file(pathname, root_dir, work_dir, work_dir):
                    count_compile[1] += 1
                else:
                    count_compile[2] += 1
        finally:
            shutil.rmtree(work_dir, ignore_errors=True)

    write_test_result()

    if count_source[2] or count_compile[2]:
        return 1
    return 0


sys.exit(__main__())
